#include <stdio.h>
#include <stdlib.h>

#define BUFFER_SIZE (1 << 16)

static char buffer[BUFFER_SIZE];
static size_t buffer_pos = 0, buffer_len = 0;

static int next_char(void) {
    if (buffer_pos == buffer_len) {
        buffer_len = fread(buffer, 1, BUFFER_SIZE, stdin);
        buffer_pos = 0;
        if (buffer_len == 0) return EOF;
    }
    return buffer[buffer_pos++];
}

static int read_int(void) {
    int c = next_char();
    while (c != EOF && c <= ' ') c = next_char();

    int value = 0;
    while (c >= '0' && c <= '9') {
        value = value * 10 + (c - '0');
        c = next_char();
    }
    return value;
}

int main(void) {
    int E = read_int();
    int M = read_int();
    int D = read_int();

    int total = M + D;
    int *a = (int *)malloc((size_t)total * sizeof(int));
    int *b = (int *)malloc((size_t)total * sizeof(int));
    int *group = (int *)malloc(((size_t)E + 1) * sizeof(int));
    unsigned char *liked = (unsigned char *)malloc((size_t)total);

    if (a == NULL || b == NULL || group == NULL || liked == NULL) {
        free(a);
        free(b);
        free(group);
        free(liked);
        return 0;
    }

    for (int i = 0; i < M; i++) {
        a[i] = read_int();
        b[i] = read_int();
        liked[i] = 1;
    }
    for (int i = M; i < total; i++) {
        a[i] = read_int();
        b[i] = read_int();
        liked[i] = 0;
    }

    for (int g = 0; g < E / 3; g++) {
        int i = read_int();
        int j = read_int();
        int k = read_int();
        group[i] = g;
        group[j] = g;
        group[k] = g;
    }

    long long violations = 0;
    for (int i = 0; i < total; i++) {
        int together = (group[a[i]] == group[b[i]]);
        if ((liked[i] && !together) || (!liked[i] && together)) {
            violations++;
        }
    }

    printf("%lld\n", violations);

    free(a);
    free(b);
    free(group);
    free(liked);
    return 0;
}
